## Recursive palindrome check

------------------------------------------
#include <stdio.h>
#include <string.h>
#include <stdbool.h>

bool isPal(const char *s, int lo, int hi) {
    if (lo >= hi)               /* 0 or 1 character left */
        return true;
    if (s[lo] != s[hi])         /* outer pair differs */
        return false;
    return isPal(s, lo + 1, hi - 1);
}

bool isPalindrome(const char *s) {
    return isPal(s, 0, (int)strlen(s) - 1);
}

int main(void) {
    printf("madam: %s\n", isPalindrome("madam") ? "true" : "false");
    printf("level: %s\n", isPalindrome("level") ? "true" : "false");
    printf("hello: %s\n", isPalindrome("hello") ? "true" : "false");
    return 0;
}
------------------------------------------

## Output

------------------------------------------
madam: true
level: true
hello: false
------------------------------------------

• Compare the outer pair s[lo] and s[hi]; if they match, check the inner part s[lo+1 .. hi−1].
• Base case: lo >= hi (zero or one character left) is a palindrome; a mismatch returns false at once.
• Time O(n), stack depth n/2.

